-- Load facilities.FactFacilityOwnership (fact).
-- One stored procedure per destination table (DE Policy v2, 5.3).
-- Generated by `python -m fde render` from models/gold/facilities/FactFacilityOwnership.yml. Do not edit: change the spec and render again.

CREATE OR ALTER PROCEDURE [facilities].[LoadFactFacilityOwnership]
    @LoadDate date,
    @LoadStepID varchar(36)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Now datetime2(6) = SYSUTCDATETIME();
    DECLARE @MaxKey bigint = (SELECT COALESCE(MAX([FactFacilityOwnership_SK]), 0)
                              FROM [facilities].[FactFacilityOwnership] WHERE [FactFacilityOwnership_SK] > 0);

    MERGE [facilities].[FactFacilityOwnership] AS target
    USING (
        SELECT
            CAST(s.[FacilityOwnership_BK] AS int) AS [FacilityOwnership_BK],
            CAST(s.[DimFacility_SK] AS bigint) AS [DimFacility_SK],
            CAST(s.[DimDataSource_SK] AS bigint) AS [DimDataSource_SK],
            CAST(s.[OwnershipYear] AS int) AS [OwnershipYear],
            CAST(s.[Owners] AS varchar(400)) AS [Owners],
            CAST(s.[Operators] AS varchar(300)) AS [Operators],
            @MaxKey + ROW_NUMBER() OVER (ORDER BY s.[FacilityOwnership_BK]) AS [NewKey]
        FROM [stage].[FactFacilityOwnershipSource] AS s
    ) AS source
    ON target.[FacilityOwnership_BK] = source.[FacilityOwnership_BK]
    WHEN MATCHED AND (
        (target.[DimFacility_SK] <> source.[DimFacility_SK] OR (target.[DimFacility_SK] IS NULL AND source.[DimFacility_SK] IS NOT NULL) OR (target.[DimFacility_SK] IS NOT NULL AND source.[DimFacility_SK] IS NULL))
        OR (target.[DimDataSource_SK] <> source.[DimDataSource_SK] OR (target.[DimDataSource_SK] IS NULL AND source.[DimDataSource_SK] IS NOT NULL) OR (target.[DimDataSource_SK] IS NOT NULL AND source.[DimDataSource_SK] IS NULL))
        OR (target.[OwnershipYear] <> source.[OwnershipYear] OR (target.[OwnershipYear] IS NULL AND source.[OwnershipYear] IS NOT NULL) OR (target.[OwnershipYear] IS NOT NULL AND source.[OwnershipYear] IS NULL))
        OR (target.[Owners] <> source.[Owners] OR (target.[Owners] IS NULL AND source.[Owners] IS NOT NULL) OR (target.[Owners] IS NOT NULL AND source.[Owners] IS NULL))
        OR (target.[Operators] <> source.[Operators] OR (target.[Operators] IS NULL AND source.[Operators] IS NOT NULL) OR (target.[Operators] IS NOT NULL AND source.[Operators] IS NULL))
    ) THEN UPDATE SET
        [DimFacility_SK] = source.[DimFacility_SK],
        [DimDataSource_SK] = source.[DimDataSource_SK],
        [OwnershipYear] = source.[OwnershipYear],
        [Owners] = source.[Owners],
        [Operators] = source.[Operators],
        [LastUpdateLoadStepID] = @LoadStepID,
        [LastUpdateTimestamp] = @Now
    WHEN NOT MATCHED BY TARGET THEN INSERT (
        [FactFacilityOwnership_SK],
        [FacilityOwnership_BK],
        [DimFacility_SK],
        [DimDataSource_SK],
        [OwnershipYear],
        [Owners],
        [Operators],
        [InsertLoadStepID],
        [InsertTimestamp],
        [LastUpdateLoadStepID],
        [LastUpdateTimestamp]
    ) VALUES (
        source.[NewKey],
        source.[FacilityOwnership_BK],
        source.[DimFacility_SK],
        source.[DimDataSource_SK],
        source.[OwnershipYear],
        source.[Owners],
        source.[Operators],
        @LoadStepID,
        @Now,
        @LoadStepID,
        @Now
    );
END
GO
